function evidence = f90_xbatt08_extract_candidate_evidence( ...
        modelPath, outputDir)
%F90_XBATT08_EXTRACT_CANDIDATE_EVIDENCE Replay the public KERS contract.
arguments
    modelPath (1,1) string
    outputDir (1,1) string
end
[taskRoot, sharedRoot] = localRoots("F90-XBATT-08");
addpath(sharedRoot, "-begin");
cleanup = onCleanup(@() rmpath(sharedRoot)); %#ok<NASGU>
official = jsondecode(fileread(simuverity_official_scenarios_path()));
spec = struct( ...
    "schema", "simuverity.f90-xbatt08-evidence.v1", ...
    "task_id", "F90-XBATT-08", ...
    "scenarios", official.scenarios, ...
    "output_contract", localOutputs, ...
    "input_builder", @localInputs, ...
    "requested_input_builder", @localRequested, ...
    "stop_time", @(~,~) 100.0, ...
    "postprocess", @localPostprocess, ...
    "static_audit", @localAudit, ...
    "coverage_mode", "event_terminated", ...
    "evidence_sample_s", 0.5);
evidence = simuverity_run_candidate_evidence( ...
    modelPath, outputDir, spec);
end

function rows = localOutputs
rows = localRows(["vehicle_speed", "traction", "storage_voltage", ...
    "storage_current", "storage_power"], [1 3 3 2 2]);
end

function inputs = localInputs(scenario, ~)
inputs = struct("kers_input", struct( ...
    "strategy_mode", double(scenario.strategy_mode), ...
    "battery_mass_kg", double(scenario.battery_mass_kg), ...
    "ultracapacitor_mass_kg", ...
        double(scenario.ultracapacitor_mass_kg), ...
    "motor_generator_mass_kg", ...
        double(scenario.motor_generator_mass_kg)));
end

function requested = localRequested(scenario, ~)
requested = rmfield(scenario, "id");
end

function row = localPostprocess(row, outputs, ~, ~)
t = double(outputs.time_s(:));
row.logs = struct( ...
    "vehicle_speed", localLog(t, outputs.vehicle_speed, ...
        {"vehicle_speed_kph"}, {"km/hr"}), ...
    "traction", localLog(t, outputs.traction, ...
        {"motor_torque_Nm", "motor_speed_rad_s", ...
         "motor_mechanical_power_W"}, {"N*m", "rad/s", "W"}), ...
    "storage_voltage", localLog(t, outputs.storage_voltage, ...
        {"battery_voltage_V", "ultracapacitor_voltage_V", ...
         "dc_bus_voltage_V"}, {"V", "V", "V"}), ...
    "storage_current", localLog(t, outputs.storage_current, ...
        {"battery_current_A", "ultracapacitor_current_A"}, ...
        {"A", "A"}), ...
    "storage_power", localLog(t, outputs.storage_power, ...
        {"battery_power_W", "ultracapacitor_power_W"}, ...
        {"W", "W"}));
row.lap_completion_s = t(end);
row.outputs = outputs;
row.valid = row.output_contract.all_required_pass && ...
    numel(t) >= 100 && t(1) <= 1e-9 && ...
    t(end) >= 80.0 && t(end) <= 100.0 + 1e-9;
end

function log = localLog(time, data, channels, units)
log = struct("time", time, "data", double(data), ...
    "channels", {channels}, "units", {units});
end

function audit = localAudit(model, spec)
structure = simuverity_candidate_structure( ...
    model, string({spec.output_contract.name})');
semantic = structure.semantic_types;
battery = nnz(contains(semantic, "battery"));
capacitor = nnz(contains(semantic, ["ultracapacitor", "supercapacitor"]));
motor = nnz(contains(semantic, ["motor", "machine"]));
audit = struct( ...
    "battery_branch_present", battery >= 1, ...
    "ultracapacitor_branch_present", capacitor >= 1, ...
    "motor_generator_path_present", motor >= 1, ...
    "connected_public_output_count", structure.connected_output_count, ...
    "dynamic_state_block_count", structure.dynamic_block_count, ...
    "core_path_qualified", battery >= 1 && capacitor >= 1 && ...
        motor >= 1 && structure.connected_output_count == ...
        numel(spec.output_contract) && structure.dynamic_block_count >= 1);
end

function rows = localRows(names, widths)
rows = repmat(struct("name", "", "evidence_name", "", ...
    "width", 0, "interpolation", "linear"), numel(names), 1);
for k = 1:numel(names)
    rows(k).name = names(k);
    rows(k).evidence_name = names(k);
    rows(k).width = widths(k);
end
end

function [taskRoot, sharedRoot] = localRoots(taskId)
scriptRoot = fileparts(mfilename("fullpath"));
tasksRoot = fileparts(scriptRoot);
sharedRoot = fullfile(tasksRoot, "_shared");
repoRoot = tasksRoot;
for k = 1:3, repoRoot = fileparts(repoRoot); end
taskRoot = string(getenv("SIMUVERITY_TASK_ROOT"));
end
